<!doctype html>
<html lang="<?php echo htmlspecialchars(I18n::getLocale()); ?>" data-theme="<?php echo htmlspecialchars(Theme::active()); ?>" data-theme-mode="<?php echo htmlspecialchars(Theme::mode()); ?>">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_title')); ?></title><link rel="stylesheet" href="../../assets/css/theme.css?v=27"><link rel="stylesheet" href="../../assets/css/inbox.css?v=79"><script>window.translations=<?php echo json_encode(I18n::exportForJs($translationNamespaces), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE); ?>;</script>
<style>
.lgs-wrap{max-width:1100px;margin:0 auto;padding:22px;color:var(--text)}.lgs-card{border:1px solid var(--border);border-radius:10px;padding:18px;margin:16px 0;background:var(--surface)}.lgs-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.lgs-field{display:flex;flex-direction:column;gap:5px;margin:8px 0}.lgs-field input,.lgs-field select{width:100%;box-sizing:border-box}.lgs-muted{color:var(--text-muted);font-size:13px}.lgs-table{width:100%;border-collapse:collapse}.lgs-table th,.lgs-table td{text-align:left;padding:8px;border-bottom:1px solid var(--border);vertical-align:middle}.lgs-table input,.lgs-table select{max-width:100%}.lgs-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.lgs-msg{padding:10px;border:1px solid var(--border);border-radius:8px;margin:12px 0}.lgs-inline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.lgs-inline input{min-width:150px}.lgs-inline select{min-width:140px}@media(max-width:750px){.lgs-grid{grid-template-columns:1fr}.lgs-table{font-size:13px}.lgs-table th,.lgs-table td{padding:5px}}
</style></head><body>
<?php include '../includes/header.php'; ?>
<main class="lgs-wrap"><div class="lgs-actions"><div style="flex:1"><h1 style="margin:0 0 5px"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_title')); ?></h1><p class="lgs-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_intro')); ?></p></div><a class="btn btn-secondary" href="index.php"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.back_to_logistics')); ?></a></div>
<div id="lgsMessage" class="lgs-msg" role="status" aria-live="polite" hidden></div>
<section class="lgs-card"><h2><?php echo htmlspecialchars(I18n::t('asset-management.logistics.movement_purposes')); ?></h2><p class="lgs-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_purpose_intro')); ?></p><div id="lgsPurposes"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.loading_purposes_text')); ?></div>
<h3><?php echo htmlspecialchars(I18n::t('asset-management.logistics.add_purpose')); ?></h3><form id="lgsAddPurpose" class="lgs-inline"><select name="movement_type" aria-label="<?php echo htmlspecialchars(I18n::t('asset-management.logistics.movement_type_aria')); ?>"><option value="outbound_dispatch"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.outbound_dispatch')); ?></option><option value="inbound_return"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.inbound_return')); ?></option></select><input name="name" maxlength="100" required placeholder="<?php echo htmlspecialchars(I18n::t('asset-management.logistics.purpose_name_placeholder')); ?>"><input name="display_order" type="number" min="0" value="50" required aria-label="<?php echo htmlspecialchars(I18n::t('asset-management.logistics.display_order_aria')); ?>"><button class="btn btn-primary" type="submit"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.add_purpose_button')); ?></button></form></section>
<section class="lgs-card"><h2><?php echo htmlspecialchars(I18n::t('asset-management.logistics.carriers_title')); ?></h2><p class="lgs-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.carriers_intro')); ?></p><div id="lgsCarriers"></div></section>
<section class="lgs-card"><h2><?php echo htmlspecialchars(I18n::t('asset-management.logistics.completion_behaviour')); ?></h2><p class="lgs-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_policy_intro')); ?></p><div class="lgs-grid" id="lgsPolicies"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.loading_policies_text')); ?></div><div class="lgs-actions"><button id="lgsSavePolicies" class="btn btn-primary" type="button"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.save_policies_button')); ?></button></div></section>
<section class="lgs-card"><h2><?php echo htmlspecialchars(I18n::t('asset-management.logistics.inspection_outcome_mapping')); ?></h2><p class="lgs-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_outcome_intro')); ?></p><div id="lgsOutcomes"></div><div class="lgs-actions"><button id="lgsSaveOutcomes" class="btn btn-primary" type="button"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.save_outcomes_button')); ?></button></div></section>
</main>
<script>
(function(){
 const tr=(key)=>((window.translations||{})['asset-management']||{}).logistics?.[key]||key;
 const api='../../api/assets/logistics.php', msg=document.getElementById('lgsMessage'); let cfg=null;
 const types=[['outbound_dispatch',tr('outbound_dispatch')],['inbound_return',tr('inbound_return')]];
 const outcomes=[['passed',tr('passed')],['minor_wear',tr('minor_wear')],['damaged',tr('damaged')],['scrap',tr('scrap')]];
 function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
 function say(s,bad=false){msg.hidden=false;msg.textContent=s;msg.style.borderColor=bad?'var(--danger,#c33)':'var(--border)';}
 async function call(action,data={}){const r=await fetch(api,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...data})});let j;try{j=await r.json()}catch(e){throw new Error(tr('unexpected_server_response'));}if(!r.ok||!j.success)throw new Error(j.error||tr('request_failed'));return j;}
 function statusOptions(selected){return '<option value="">'+tr('status_not_change')+'</option>'+cfg.statuses.map(s=>'<option value="'+Number(s.id)+'" '+(String(selected||'')===String(s.id)?'selected':'')+'>'+esc(s.name)+'</option>').join('');}
 function renderPurposes(){document.getElementById('lgsPurposes').innerHTML='<table class="lgs-table"><thead><tr><th>'+tr('type')+'</th><th>'+tr('name')+'</th><th>'+tr('order')+'</th><th>'+tr('active')+'</th><th>'+tr('scope')+'</th><th></th></tr></thead><tbody>'+cfg.purposes.map(p=>{const shared=p.tenant_id==null;return '<tr data-purpose="'+Number(p.id)+'"><td>'+esc(p.movement_type==='outbound_dispatch'?tr('outbound_short'):tr('inbound_short'))+'</td><td><input name="name" maxlength="100" value="'+esc(p.name)+'" aria-label="'+tr('purpose_name_aria')+'" '+'></td><td><input name="display_order" type="number" min="0" value="'+Number(p.display_order)+'" style="width:80px" aria-label="'+tr('purpose_order_aria')+'" '+'></td><td><input name="is_active" type="checkbox" '+(Number(p.is_active)?'checked':'')+' aria-label="'+tr('purpose_active_aria')+'" '+'></td><td>'+esc(shared?tr('scope_shared_default'):tr('scope_company'))+'</td><td>'+'<button type="button" class="btn btn-secondary" data-save-purpose="'+Number(p.id)+'">'+(shared?tr('save_company_override'):tr('save_purpose_button'))+'</button>'+'</td></tr>';}).join('')+'</tbody></table>';
 document.querySelectorAll('[data-save-purpose]').forEach(b=>b.addEventListener('click',async()=>{const row=b.closest('tr'),id=Number(b.dataset.savePurpose),p=cfg.purposes.find(x=>Number(x.id)===id);try{await call('save_purpose',{id,movement_type:p.movement_type,original_movement_type:p.movement_type,name:row.querySelector('[name=name]').value,display_order:Number(row.querySelector('[name=display_order]').value),is_active:row.querySelector('[name=is_active]').checked?1:0});await load();say(tr('purpose_saved'));}catch(e){say(e.message,true);}}));}
 function renderPolicies(){const map={};cfg.policies.forEach(p=>map[p.movement_type]=p);document.getElementById('lgsPolicies').innerHTML=types.map(([type,label])=>{const p=map[type]||{};const update=type==='outbound_dispatch'&&Number(p.update_asset_status_on_completion||0)===1;return '<div class="lgs-card" style="margin:0"><h3>'+label+'</h3><input type="hidden" name="movement_type" value="'+type+'"><div class="lgs-field"><label><input type="checkbox" name="close_movement_on_completion" '+(p.close_movement_on_completion==null||Number(p.close_movement_on_completion)===1?'checked':'')+'>'+tr('completion_close_help')+'</label></div><div class="lgs-field"><label><input type="checkbox" name="assign_to_recipient_on_ack" '+(type==='outbound_dispatch'&&(p.assign_to_recipient_on_ack==null||Number(p.assign_to_recipient_on_ack)===1)?'checked':'')+' '+(type==='inbound_return'?'disabled':'')+'>'+tr('assign_after_ack_help')+'</label><span class="lgs-muted">'+tr('assign_policy_detail')+'</span></div><div class="lgs-field"><label><input type="checkbox" name="update_asset_status_on_completion" '+(update?'checked':'')+' '+(type==='inbound_return'?'disabled':'')+'>'+tr('status_update_label')+'</label></div><div class="lgs-field"><label>'+tr('status_to_apply_label')+'</label><select name="completion_asset_status_id" '+(update?'':'disabled')+' '+(type==='inbound_return'?'disabled':'')+'>'+statusOptions(p.completion_asset_status_id)+'</select><span class="lgs-muted">'+(type==='inbound_return'?tr('return_status_policy_detail'):tr('status_update_policy_detail'))+'</span></div><div class="lgs-field"><label>'+tr('receipt_inspection')+'</label><select name="post_receipt_action"><option value="none" '+((p.post_receipt_action||'none')==='none'?'selected':'')+'>'+tr('inspection_not_required_label')+'</option><option value="inspection" '+(p.post_receipt_action==='inspection'?'selected':'')+'>'+tr('inspection_required_label')+'</option></select></div><div class="lgs-field"><label>'+tr('inspection_method')+'</label><select name="inspection_provider" '+(p.post_receipt_action==='inspection'?'':'disabled')+'><option value="">'+tr('inspection_method_choose')+'</option><option value="manual" '+(p.inspection_provider==='manual'?'selected':'')+'>'+tr('manual_inspection_available')+'</option></select></div></div>';}).join('');document.querySelectorAll('#lgsPolicies [name=update_asset_status_on_completion]').forEach(el=>el.addEventListener('change',()=>{el.closest('.lgs-card').querySelector('[name=completion_asset_status_id]').disabled=!el.checked;}));document.querySelectorAll('#lgsPolicies [name=post_receipt_action]').forEach(el=>el.addEventListener('change',()=>{el.closest('.lgs-card').querySelector('[name=inspection_provider]').disabled=el.value!=='inspection';}));}
 function renderCarriers(){const rows=cfg.carriers||[];document.getElementById('lgsCarriers').innerHTML='<table class="lgs-table"><thead><tr><th>'+tr('carrier_supplier')+'</th><th>'+tr('enabled')+'</th><th>'+tr('default')+'</th><th>'+tr('tracking_url_air')+'</th><th>'+tr('tracking_url_surface')+'</th><th></th></tr></thead><tbody>'+rows.map(c=>'<tr data-carrier="'+Number(c.supplier_id)+'"><td>'+esc(c.name)+'</td><td><input type="checkbox" name="enabled" '+(Number(c.carrier_active)?'checked':'')+'></td><td><input type="radio" name="defaultCarrier" '+(Number(c.is_default)?'checked':'')+' '+(Number(c.carrier_active)?'':'disabled')+'></td><td><input name="tracking_url_air" maxlength="1000" style="min-width:240px" placeholder="https://carrier.example/air-track" value="'+esc(c.tracking_url_air||'')+'"></td><td><input name="tracking_url_surface" maxlength="1000" style="min-width:240px" placeholder="https://carrier.example/track?ref={tracking_number}" value="'+esc(c.tracking_url_surface||'')+'"></td><td><button type="button" class="btn btn-secondary" data-save-carrier="'+Number(c.supplier_id)+'">Save</button></td></tr>').join('')+'</tbody></table><p class="lgs-muted">'+tr('tracking_url_placeholder_hint')+'</p>';
 document.querySelectorAll('[data-save-carrier]').forEach(b=>b.addEventListener('click',async()=>{const row=b.closest('tr'),supplier_id=Number(b.dataset.saveCarrier),is_default=!!row.querySelector('[name=defaultCarrier]').checked;try{await call('save_carrier',{supplier_id,is_active:row.querySelector('[name=enabled]').checked?1:0,is_default:is_default?1:0,tracking_url_air:row.querySelector('[name=tracking_url_air]').value,tracking_url_surface:row.querySelector('[name=tracking_url_surface]').value});await load();say(tr('carrier_saved'));}catch(e){say(e.message,true);}}));}
 function renderOutcomes(){const map={};cfg.outcome_statuses.forEach(o=>map[o.outcome_code]=o.asset_status_id);document.getElementById('lgsOutcomes').innerHTML='<table class="lgs-table"><thead><tr><th>'+tr('outcome')+'</th><th>'+tr('asset_status')+'</th></tr></thead><tbody>'+outcomes.map(([code,label])=>'<tr><td>'+label+' <code>'+code+'</code></td><td><select data-outcome="'+code+'">'+statusOptions(map[code])+'</select></td></tr>').join('')+'</tbody></table>';}
 async function load(){cfg=await call('get_configuration');renderPurposes();renderPolicies();renderOutcomes();renderCarriers();}
 document.getElementById('lgsAddPurpose').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await call('save_purpose',{movement_type:f.get('movement_type'),name:f.get('name'),display_order:Number(f.get('display_order')),is_active:1});e.currentTarget.reset();await load();say(tr('purpose_added'));}catch(err){say(err.message,true);}});
 document.getElementById('lgsSavePolicies').addEventListener('click',async()=>{try{for(const card of document.querySelectorAll('#lgsPolicies .lgs-card')){const get=n=>card.querySelector('[name="'+n+'"]');await call('save_receipt_policy',{movement_type:get('movement_type').value,post_receipt_action:get('post_receipt_action').value,inspection_provider:get('inspection_provider').value,close_movement_on_completion:get('close_movement_on_completion').checked?1:0,assign_to_recipient_on_ack:get('assign_to_recipient_on_ack').checked?1:0,update_asset_status_on_completion:get('update_asset_status_on_completion').checked?1:0,completion_asset_status_id:get('completion_asset_status_id').value||null});}await load();say(tr('policies_saved'));}catch(e){say(e.message,true);}});
 document.getElementById('lgsSaveOutcomes').addEventListener('click',async()=>{try{for(const sel of document.querySelectorAll('[data-outcome]'))await call('save_outcome_status',{outcome_code:sel.dataset.outcome,asset_status_id:sel.value||null});await load();say(tr('outcomes_saved'));}catch(e){say(e.message,true);}});
 load().catch(e=>say(e.message,true));
})();
</script></body></html>
